#!/usr/bin/env python3
"""World News in One Image - Tuesday 17 November 2026.

Entry for the make.fun bounty news-image-20261117: one image summing up
the world's news of Tuesday 17 November 2026. Variant 1 of 3: a
front-page newspaper grid with a big masthead, the Kerch Bridge lead
story and six illustrated panels.

Writes the final image to /output/entry.png (or $MAKEFUN_OUTPUT_DIR
when set). Standard library only, no network, deterministic: every run
writes the same bytes.
The embedded image is the front-page grid: masthead, Kerch Bridge lead
and six illustrated panels, all text drawn with PIL so it stays sharp.
"""

import base64
import os

IMAGE_B64 = ""

def main():
    out_dir = os.environ.get("MAKEFUN_OUTPUT_DIR", "/output")
    os.makedirs(out_dir, exist_ok=True)
    data = base64.b64decode(IMAGE_B64)
    with open(os.path.join(out_dir, "entry.png"), "wb") as f:
        f.write(data)

if __name__ == "__main__":
    main()
